import{F as e,_ as t,f as n,g as r,h as i,j as a,l as o,n as s}from"./chunks/shared.rYHlazZf.js";var c=JSON.parse(`{"title":"Read and inspect the LIVE feed","description":"","frontmatter":{"title":"Read and inspect the LIVE feed","docId":"user.live.feed","translationKey":"user.live.feed","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"4830f0a02244f46bfefb9b37c09d96c969688d022a0df90359c96c3e359af147","translationRevision":"4830f0a02244f46bfefb9b37c09d96c969688d022a0df90359c96c3e359af147","order":20},"headers":[],"relativePath":"en/user/live/feed.md","filePath":"en/user/live/feed.md","lastUpdated":1795727787000}`),l={name:`en/user/live/feed.md`};function u(s,c,l,u,d,f){let p=e(`DemoFrame`);return a(),n(`div`,null,[c[0]||=i(`<h1 id="read-and-inspect-the-live-feed" tabindex="-1">Read and inspect the LIVE feed <a class="header-anchor" href="#read-and-inspect-the-live-feed" aria-label="Permalink to “Read and inspect the LIVE feed”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Goal and prerequisites <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “Goal and prerequisites”">​</a></h2><p>Find an event, inspect its fields and distinguish a paused display from a disconnected room. Start with a <a href="./connections.html">LIVE connection</a>, or use events already present in the current feed. The feed is a bounded working view, not a complete recording of a broadcast.</p><h2 id="inspect-activity" tabindex="-1">Inspect activity <a class="header-anchor" href="#inspect-activity" aria-label="Permalink to “Inspect activity”">​</a></h2><ol><li>Open <strong>Live feed</strong> and confirm the active creator in the connection status.</li><li>Choose an event filter: all events, chat, gifts, likes, follows, joins or other social activity. Combine it with search to find an author, message, gift name or exact gift ID.</li><li>Select <strong>Pause</strong> to stop automatic scrolling while you read. Events can continue arriving and the unread count can increase. This control does not disconnect TikTok or suspend automations.</li><li>Select an event to open its inspector. Read the event type and available details before choosing automation fields. Not every event carries chat text, gift information or a viewer identity.</li><li>Select a viewer&#39;s name or avatar to inspect their tracked profile. Use the inspector toggle if the details panel is hidden.</li><li>Select <strong>Resume</strong> or the unread-event jump button to return to incoming activity. Clear the search and select all events when checking whether activity is arriving.</li></ol><p>Use the labeled controls with keyboard focus where possible. Pausing scrolling helps when movement makes reading difficult. A missing avatar has an initials fallback; a picture is not needed to identify a viewer.</p><h2 id="expected-result-and-status" tabindex="-1">Expected result and status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “Expected result and status”">​</a></h2><p>Filtering and inspection are available. During heavy traffic, the interface can show a limited rendering window and report dropped UI events. These indicators describe the display; do not use its visible row count as an accounting total. <a href="./../points/statistics.html">Analytics</a> queries persisted aggregates separately.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to “Recovery”">​</a></h2><p>If the feed is empty, remove filters, resume scrolling and check connection status. A quiet room may be healthy. Reconnecting to the same creator retains context; switching creator changes it. <strong>Clear</strong> empties the working feed and does not reset points or analytics. Investigate loss indicators through <a href="./../preferences/troubleshooting.html">diagnostics</a>, without assuming all missing display rows are missing upstream events.</p>`,10),t(p,{scenario:`feed`,locale:`en`,title:`Demo: feed`}),c[1]||=o(`h2`,{id:`operational-details`,tabindex:`-1`},[r(`Operational details `),o(`a`,{class:`header-anchor`,href:`#operational-details`,"aria-label":`Permalink to “Operational details”`},`​`)],-1),c[2]||=o(`p`,null,`This version retains up to 300 displayed events and stages up to 900 while presentation waits. Retention evicts the oldest non-gift row first; gifts are evicted only when no other types remain. An older gift can therefore outlast a newer chat. Pausing scrolling does not stop ingestion or guarantee retention. Filters cannot restore evicted rows; a loss warning is evidence of an incomplete view, not permission to replay points or actions.`,-1)])}var d=s(l,[[`render`,u]]);export{c as __pageData,d as default};